/*
 * Create a contiguous non-refillable bit data structure.
 * Can be freed by FREEMEM().
 */
asn_bit_data_t *
asn_bit_data_new_contiguous(const void *data, size_t size_bits) {
    size_t size_bytes = (size_bits + 7) / 8;
    asn_bit_data_t *pd;
    uint8_t *bytes;

    /* Get the extensions map */
    pd = CALLOC(1, sizeof(*pd) + size_bytes + 1);
    if(!pd) {
        return NULL;
    }
    bytes = (void *)(((char *)pd) + sizeof(*pd));
    memcpy(bytes, data, size_bytes);
    bytes[size_bytes] = 0;
    pd->buffer = bytes;
    pd->nboff = 0;
    pd->nbits = size_bits;

    return pd;
}


char *
asn_bit_data_string(asn_bit_data_t *pd) {
	static char buf[2][32];
	static int n;
	n = (n+1) % 2;
    snprintf(buf[n], sizeof(buf[n]),
             "{m=%" ASN_PRI_SIZE " span %" ASN_PRI_SIZE "[%" ASN_PRI_SIZE
             "..%" ASN_PRI_SIZE "] (%" ASN_PRI_SIZE ")}",
             pd->moved, ((uintptr_t)(pd->buffer) & 0xf), pd->nboff, pd->nbits,
             pd->nbits - pd->nboff);
    return buf[n];
}

void
asn_get_undo(asn_bit_data_t *pd, int nbits) {
	if((ssize_t)pd->nboff < nbits) {
		assert((ssize_t)pd->nboff < nbits);
	} else {
		pd->nboff -= nbits;
		pd->moved -= nbits;
	}
}

/*
 * Extract a small number of bits (<= 31) from the specified PER data pointer.
 */
int32_t
asn_get_few_bits(asn_bit_data_t *pd, int nbits) {
	size_t off;	/* Next after last bit offset */
	ssize_t nleft;	/* Number of bits left in this stream */
	uint32_t accum;
	const uint8_t *buf;

	if(nbits < 0)
		return -1;

	nleft = pd->nbits - pd->nboff;
	if(nbits > nleft) {
		int32_t tailv, vhead;
		if(!pd->refill || nbits > 31) return -1;
		/* Accumulate unused bytes before refill */
		ASN_DEBUG("Obtain the rest %d bits (want %d)",
			(int)nleft, (int)nbits);
		tailv = asn_get_few_bits(pd, nleft);
		if(tailv < 0) return -1;
		/* Refill (replace pd contents with new data) */
		if(pd->refill(pd))
			return -1;
		nbits -= nleft;
		vhead = asn_get_few_bits(pd, nbits);
		/* Combine the rest of previous pd with the head of new one */
		tailv = (tailv << nbits) | vhead;  /* Could == -1 */
		return tailv;
	}

	/*
	 * Normalize position indicator.
	 */
	if(pd->nboff >= 8) {
		pd->buffer += (pd->nboff >> 3);
		pd->nbits  -= (pd->nboff & ~0x07);
		pd->nboff  &= 0x07;
	}
	pd->moved += nbits;
	pd->nboff += nbits;
	off = pd->nboff;
	buf = pd->buffer;

	/*
	 * Extract specified number of bits.
	 */
	if(off <= 8)
		accum = nbits ? (buf[0]) >> (8 - off) : 0;
	else if(off <= 16)
		accum = ((buf[0] << 8) + buf[1]) >> (16 - off);
	else if(off <= 24)
		accum = ((buf[0] << 16) + (buf[1] << 8) + buf[2]) >> (24 - off);
	else if(off <= 31)
		accum = (((uint32_t)buf[0] << 24) + (buf[1] << 16)
			+ (buf[2] << 8) + (buf[3])) >> (32 - off);
	else if(nbits <= 31) {
		asn_bit_data_t tpd = *pd;
		/* Here are we with our 31-bits limit plus 1..7 bits offset. */
		asn_get_undo(&tpd, nbits);
		/* The number of available bits in the stream allow
		 * for the following operations to take place without
		 * invoking the ->refill() function */
		accum  = asn_get_few_bits(&tpd, nbits - 24) << 24;
		accum |= asn_get_few_bits(&tpd, 24);
	} else {
		asn_get_undo(pd, nbits);
		return -1;
	}

	accum &= (((uint32_t)1 << nbits) - 1);

	ASN_DEBUG("  [PER got %2d<=%2d bits => span %d %+ld[%d..%d]:%02x (%d) => 0x%x]",
		(int)nbits, (int)nleft,
		(int)pd->moved,
		(((long)pd->buffer) & 0xf),
		(int)pd->nboff, (int)pd->nbits,
		((pd->buffer != NULL)?pd->buffer[0]:0),
		(int)(pd->nbits - pd->nboff),
		(int)accum);

	return accum;
}

/*
 * Extract a large number of bits from the specified PER data pointer.
 */
int
asn_get_many_bits(asn_bit_data_t *pd, uint8_t *dst, int alright, int nbits) {
	int32_t value;

	if(alright && (nbits & 7)) {
		/* Perform right alignment of a first few bits */
		value = asn_get_few_bits(pd, nbits & 0x07);
		if(value < 0) return -1;
		*dst++ = value;	/* value is already right-aligned */
		nbits &= ~7;
	}

	while(nbits) {
		if(nbits >= 24) {
			value = asn_get_few_bits(pd, 24);
			if(value < 0) return -1;
			*(dst++) = value >> 16;
			*(dst++) = value >> 8;
			*(dst++) = value;
			nbits -= 24;
		} else {
			value = asn_get_few_bits(pd, nbits);
			if(value < 0) return -1;
			if(nbits & 7) {	/* implies left alignment */
				value <<= 8 - (nbits & 7),
				nbits += 8 - (nbits & 7);
				if(nbits > 24)
					*dst++ = value >> 24;
			}
			if(nbits > 16)
				*dst++ = value >> 16;
			if(nbits > 8)
				*dst++ = value >> 8;
			*dst++ = value;
			break;
		}
	}

	return 0;
}

/*
 * Put a small number of bits (<= 31).
 */
int
asn_put_few_bits(asn_bit_outp_t *po, uint32_t bits, int obits) {
	size_t off;	/* Next after last bit offset */
	size_t omsk;	/* Existing last byte meaningful bits mask */
	uint8_t *buf;

	if(obits <= 0 || obits >= 32) return obits ? -1 : 0;

	ASN_DEBUG("[PER put %d bits %x to %p+%d bits]",
			obits, (int)bits, (void *)po->buffer, (int)po->nboff);

	/*
	 * Normalize position indicator.
	 */
	if(po->nboff >= 8) {
		po->buffer += (po->nboff >> 3);
		po->nbits  -= (po->nboff & ~0x07);
		po->nboff  &= 0x07;
	}

	/*
	 * Flush whole-bytes output, if necessary.
	 */
	if(po->nboff + obits > po->nbits) {
		size_t complete_bytes;
		if(!po->buffer) po->buffer = po->tmpspace;
		complete_bytes = (po->buffer - po->tmpspace);
		ASN_DEBUG("[PER output %ld complete + %ld]",
			(long)complete_bytes, (long)po->flushed_bytes);
		if(po->output(po->tmpspace, complete_bytes, po->op_key) < 0)
			return -1;
		if(po->nboff)
			po->tmpspace[0] = po->buffer[0];
		po->buffer = po->tmpspace;
		po->nbits = 8 * sizeof(po->tmpspace);
		po->flushed_bytes += complete_bytes;
	}

	/*
	 * Now, due to sizeof(tmpspace), we are guaranteed large enough space.
	 */
	buf = po->buffer;
	omsk = ~((1 << (8 - po->nboff)) - 1);
	off = (po->nboff + obits);

	/* Clear data of debris before meaningful bits */
	bits &= (((uint32_t)1 << obits) - 1);

	ASN_DEBUG("[PER out %d %u/%x (t=%d,o=%d) %x&%x=%x]", obits,
		(int)bits, (int)bits,
		(int)po->nboff, (int)off,
		buf[0], (int)(omsk&0xff),
		(int)(buf[0] & omsk));

	if(off <= 8)	/* Completely within 1 byte */
		po->nboff = off,
		bits <<= (8 - off),
		buf[0] = (buf[0] & omsk) | bits;
	else if(off <= 16)
		po->nboff = off,
		bits <<= (16 - off),
		buf[0] = (buf[0] & omsk) | (bits >> 8),
		buf[1] = bits;
	else if(off <= 24)
		po->nboff = off,
		bits <<= (24 - off),
		buf[0] = (buf[0] & omsk) | (bits >> 16),
		buf[1] = bits >> 8,
		buf[2] = bits;
	else if(off <= 31)
		po->nboff = off,
		bits <<= (32 - off),
		buf[0] = (buf[0] & omsk) | (bits >> 24),
		buf[1] = bits >> 16,
		buf[2] = bits >> 8,
		buf[3] = bits;
	else {
		if(asn_put_few_bits(po, bits >> (obits - 24), 24)) return -1;
		if(asn_put_few_bits(po, bits, obits - 24)) return -1;
	}

	ASN_DEBUG("[PER out %u/%x => %02x buf+%ld]",
		(int)bits, (int)bits, buf[0],
		(long)(po->buffer - po->tmpspace));

	return 0;
}


/*
 * Output a large number of bits.
 */
int
asn_put_many_bits(asn_bit_outp_t *po, const uint8_t *src, int nbits) {

	while(nbits) {
		uint32_t value;

		if(nbits >= 24) {
			value = (src[0] << 16) | (src[1] << 8) | src[2];
			src += 3;
			nbits -= 24;
			if(asn_put_few_bits(po, value, 24))
				return -1;
		} else {
			value = src[0];
			if(nbits > 8)
				value = (value << 8) | src[1];
			if(nbits > 16)
				value = (value << 8) | src[2];
			if(nbits & 0x07)
				value >>= (8 - (nbits & 0x07));
			if(asn_put_few_bits(po, value, nbits))
				return -1;
			break;
		}
	}

	return 0;
}


int
asn_put_aligned_flush(asn_bit_outp_t *po) {
    uint32_t unused_bits = (0x7 & (8 - (po->nboff & 0x07)));
    size_t complete_bytes =
        (po->buffer ? po->buffer - po->tmpspace : 0) + ((po->nboff + 7) >> 3);

    if(unused_bits) {
        po->buffer[po->nboff >> 3] &= ~0u << unused_bits;
    }

    if(po->output(po->tmpspace, complete_bytes, po->op_key) < 0) {
        return -1;
    } else {
        po->buffer = po->tmpspace;
        po->nboff = 0;
        po->nbits = 8 * sizeof(po->tmpspace);
        po->flushed_bytes += complete_bytes;
        return 0;
    }
}

/* ---- asn_codecs_prim.c ---- */
/*-
 * Copyright (c) 2003, 2004 Lev Walkin <vlm@lionet.info>. All rights reserved.
 * Redistribution and modifications are permitted subject to BSD license.
 */

void
ASN__PRIMITIVE_TYPE_free(const asn_TYPE_descriptor_t *td, void *sptr,
                         enum asn_struct_free_method method) {
    ASN__PRIMITIVE_TYPE_t *st = (ASN__PRIMITIVE_TYPE_t *)sptr;

	if(!td || !sptr)
		return;

	ASN_DEBUG("Freeing %s as a primitive type", td->name);

	if(st->buf)
		FREEMEM(st->buf);

    switch(method) {
    case ASFM_FREE_EVERYTHING:
        FREEMEM(sptr);
        break;
    case ASFM_FREE_UNDERLYING:
        break;
    case ASFM_FREE_UNDERLYING_AND_RESET:
        memset(sptr, 0, sizeof(ASN__PRIMITIVE_TYPE_t));
        break;
    }
}
/* ---- asn_constraint_value.c ---- */
/*-
 * Runtime helpers for asn_cval_t constraint bounds.  See asn_constraint_value.h.
 */
#include <errno.h>

/* ===== canonical two's-complement content-octet comparison ===== */

/* A bound's content octets are negative iff the top bit of the first octet
 * is set (and there is at least one octet). */
static int
acv_bytes_negative(const uint8_t *buf, size_t size) {
    return (size > 0) && (buf[0] & 0x80);
}

/*
 * Defensive canonicalization: return a pointer/length pair stripped of
 * redundant leading sign octets.  Operates on the caller's buffer (no copy).
 */
static void
acv_bytes_canonical(const uint8_t *buf, size_t size,
                    const uint8_t **out_buf, size_t *out_size) {
    if(size == 0) {
        *out_buf = buf;
        *out_size = 0;
        return;
    }
    if(buf[0] & 0x80) {
        /* negative: drop leading 0xFF while next octet keeps the sign bit */
        while(size > 1 && buf[0] == 0xFF && (buf[1] & 0x80)) {
            buf++;
            size--;
        }
    } else {
        /* non-negative: drop leading 0x00 while next octet lacks the sign bit */
        while(size > 1 && buf[0] == 0x00 && !(buf[1] & 0x80)) {
            buf++;
            size--;
        }
    }
    *out_buf = buf;
    *out_size = size;
}

/* Compare two canonical INTEGER content-octet arrays as signed integers. */
static int
acv_cmp_bytes(const uint8_t *ab, size_t as, const uint8_t *bb, size_t bs) {
    int an, bn;
    acv_bytes_canonical(ab, as, &ab, &as);
    acv_bytes_canonical(bb, bs, &bb, &bs);
    an = acv_bytes_negative(ab, as);
    bn = acv_bytes_negative(bb, bs);
    if(an != bn)
        return an ? -1 : 1;     /* negative < non-negative */
    if(!an) {
        /* both non-negative: longer canonical form is larger */
        if(as != bs) return as < bs ? -1 : 1;
        return memcmp(ab, bb, as);
    } else {
        /* both negative: longer canonical form is more negative (smaller) */
        if(as != bs) return as < bs ? 1 : -1;
        /* same width two's complement: unsigned order == signed order */
        return memcmp(ab, bb, as);
    }
}

/* Materialize a scalar as canonical content octets into an INTEGER_t. */
static int
acv_sint_to_INTEGER(intmax_t v, INTEGER_t *tmp) {
    memset(tmp, 0, sizeof(*tmp));
    return asn_imax2INTEGER(tmp, v);
}
static int
acv_uint_to_INTEGER(uintmax_t v, INTEGER_t *tmp) {
    memset(tmp, 0, sizeof(*tmp));
    return asn_umax2INTEGER(tmp, v);
}

/* Compare a materialized scalar (as INTEGER_t bytes) against cval bytes. */
static int
acv_cmp_scalarbytes_vs_cvalbytes(const INTEGER_t *s, const asn_cval_t *b) {
    return acv_cmp_bytes(s->buf, s->size, b->value.b.buf, b->value.b.size);
}

/* ===== scalar vs cval ===== */

int
asn_cval_cmp_uint(uintmax_t a, const asn_cval_t *b) {
    switch(b->kind) {
    case ACV_UINT:
        if(a < b->value.u) return -1;
        if(a > b->value.u) return 1;
        return 0;
    case ACV_SINT:
        if(b->value.s < 0) return 1;                  /* a >= 0 > b */
        if(a < (uintmax_t)b->value.s) return -1;
        if(a > (uintmax_t)b->value.s) return 1;
        return 0;
    case ACV_INTEGER_BYTES: {
        INTEGER_t tmp;
        int r;
        if(acv_uint_to_INTEGER(a, &tmp) != 0) return 0;
        r = acv_cmp_scalarbytes_vs_cvalbytes(&tmp, b);
        if(tmp.buf) FREEMEM(tmp.buf);
        return r;
    }
    case ACV_ABSENT:
    default:
        return 0;
    }
}

int
asn_cval_cmp_sint(intmax_t a, const asn_cval_t *b) {
    switch(b->kind) {
    case ACV_SINT:
        if(a < b->value.s) return -1;
        if(a > b->value.s) return 1;
        return 0;
    case ACV_UINT:
        if(a < 0) return -1;                          /* a < 0 <= b */
        if((uintmax_t)a < b->value.u) return -1;
        if((uintmax_t)a > b->value.u) return 1;
        return 0;
    case ACV_INTEGER_BYTES: {
        INTEGER_t tmp;
        int r;
        if(acv_sint_to_INTEGER(a, &tmp) != 0) return 0;
        r = acv_cmp_scalarbytes_vs_cvalbytes(&tmp, b);
        if(tmp.buf) FREEMEM(tmp.buf);
        return r;
    }
    case ACV_ABSENT:
    default:
        return 0;
    }
}

/* Convert a cval scalar into canonical content octets in *tmp. */
static int
acv_to_INTEGER(const asn_cval_t *v, INTEGER_t *tmp, int *materialized) {
    *materialized = 0;
    switch(v->kind) {
    case ACV_SINT:
        if(acv_sint_to_INTEGER(v->value.s, tmp) != 0) return -1;
        *materialized = 1;
        return 0;
    case ACV_UINT:
        if(acv_uint_to_INTEGER(v->value.u, tmp) != 0) return -1;
        *materialized = 1;
        return 0;
    case ACV_INTEGER_BYTES: {
        /* Copy the read-only bytes into an owned buffer.
         * Aliasing v->value.b.buf (const uint8_t *) directly into tmp->buf
         * (uint8_t *) would drop const.  A copy is correct and lets the
         * existing materialized=1 cleanup path (FREEMEM) handle it. */
        size_t sz = v->value.b.size;
        tmp->buf = (uint8_t *)MALLOC(sz ? sz : 1);
        if(!tmp->buf) return -1;
        memcpy(tmp->buf, v->value.b.buf, sz);
        tmp->size = sz;
        *materialized = 1;
        return 0;
    }
    case ACV_ABSENT:
    default:
        return -1;
    }
}

int
asn_cval_cmp(const asn_cval_t *a, const asn_cval_t *b) {
    /* Fast scalar paths */
    if(a->kind == ACV_SINT) return asn_cval_cmp_sint(a->value.s, b);
    if(a->kind == ACV_UINT) return asn_cval_cmp_uint(a->value.u, b);
    if(a->kind == ACV_INTEGER_BYTES) {
        INTEGER_t tb;
        int mat = 0, r;
        if(b->kind == ACV_INTEGER_BYTES)
            return acv_cmp_bytes(a->value.b.buf, a->value.b.size,
                                 b->value.b.buf, b->value.b.size);
        if(acv_to_INTEGER(b, &tb, &mat) != 0) return 0;
        r = acv_cmp_bytes(a->value.b.buf, a->value.b.size, tb.buf, tb.size);
        if(mat && tb.buf) FREEMEM(tb.buf);
        return r;
    }
    return 0;
}

/* ===== INTEGER_t vs cval ===== */

int
asn_INTEGER_cmp_cval(const INTEGER_t *a, const asn_cval_t *b,
                     int a_is_unsigned) {
    /* Try the scalar fast paths first. */
    if(a_is_unsigned) {
        uintmax_t uv;
        if(asn_INTEGER2umax(a, &uv) == 0)
            return asn_cval_cmp_uint(uv, b);
    } else {
        intmax_t sv;
        if(asn_INTEGER2imax(a, &sv) == 0)
            return asn_cval_cmp_sint(sv, b);
    }
    /* Value does not fit a native scalar: compare canonical octets. */
    {
        INTEGER_t tb;
        int mat = 0, r;
        if(b->kind == ACV_INTEGER_BYTES) {
            return acv_cmp_bytes(a->buf, a->size,
                                 b->value.b.buf, b->value.b.size);
        }
        if(acv_to_INTEGER(b, &tb, &mat) != 0) return 0;
        r = acv_cmp_bytes(a->buf, a->size, tb.buf, tb.size);
        if(mat && tb.buf) FREEMEM(tb.buf);
        return r;
    }
}

/* ===== range checks ===== */

int
asn_check_integer_range_sint(intmax_t value,
                             const asn_cval_t *lb, const asn_cval_t *ub) {
    if(lb && lb->kind != ACV_ABSENT && asn_cval_cmp_sint(value, lb) < 0)
        return -1;
    if(ub && ub->kind != ACV_ABSENT && asn_cval_cmp_sint(value, ub) > 0)
        return -1;
    return 0;
}

int
asn_check_integer_range_uint(uintmax_t value,
                             const asn_cval_t *lb, const asn_cval_t *ub) {
    if(lb && lb->kind != ACV_ABSENT && asn_cval_cmp_uint(value, lb) < 0)
        return -1;
    if(ub && ub->kind != ACV_ABSENT && asn_cval_cmp_uint(value, ub) > 0)
        return -1;
    return 0;
}

int
asn_check_INTEGER_range(const INTEGER_t *value,
                        const asn_cval_t *lb, const asn_cval_t *ub,
                        int value_is_unsigned) {
    if(lb && lb->kind != ACV_ABSENT
       && asn_INTEGER_cmp_cval(value, lb, value_is_unsigned) < 0)
        return -1;
    if(ub && ub->kind != ACV_ABSENT
       && asn_INTEGER_cmp_cval(value, ub, value_is_unsigned) > 0)
        return -1;
    return 0;
}

/* ===== v2 range arithmetic ===== */

/* Extract a scalar bound as a uintmax_t offset from 0; returns 0 on success.
 * For ACV_INTEGER_BYTES (beyond uintmax) returns -1 (caller treats as big). */
static int
acv_as_imax(const asn_cval_t *v, intmax_t *out) {
    switch(v->kind) {
    case ACV_SINT: *out = v->value.s; return 0;
    case ACV_UINT:
        if(v->value.u > (uintmax_t)INTMAX_MAX) return -1;
        *out = (intmax_t)v->value.u; return 0;
    default: return -1;
    }
}

int
asn_cval_compute_range(const asn_cval_t *lb, const asn_cval_t *ub,
                       asn_range_info_t *out) {
    intmax_t l, u;
    uintmax_t range_minus_1;
    int bits;

    if(!out) return -1;
    out->kind = ASN_RANGE_UNCONSTRAINED;
    out->u64_range = 0;
    out->range_bits = -1;
    out->effective_bits = -1;

    if(!lb || !ub || lb->kind == ACV_ABSENT || ub->kind == ACV_ABSENT)
        return -1;   /* open range: unconstrained for this helper */

    /* Big bounds are out of scope for the native fast path. */
    if(lb->kind == ACV_INTEGER_BYTES || ub->kind == ACV_INTEGER_BYTES) {
        out->kind = ASN_RANGE_BIG;
        return -1;
    }

    /*
     * Compute (ub - lb) as an unsigned magnitude without overflow.  Both
     * bounds fit intmax_t here (UINT bounds above INTMAX_MAX are rare for
     * native ranges; if encountered, fall back to big).
     */
    if(ub->kind == ACV_UINT && lb->kind == ACV_UINT) {
        if(ub->value.u < lb->value.u) return -1;
        range_minus_1 = ub->value.u - lb->value.u;
    } else if(acv_as_imax(lb, &l) == 0 && acv_as_imax(ub, &u) == 0) {
        if(u < l) return -1;
        /* u - l fits uintmax_t even across the sign boundary */
        range_minus_1 = (uintmax_t)u - (uintmax_t)l;
    } else {
        out->kind = ASN_RANGE_BIG;
        return -1;
    }

    /* range = range_minus_1 + 1; guard the all-ones case. */
    if(range_minus_1 == UINTMAX_MAX) {
        out->kind = ASN_RANGE_BIG;   /* range == 2^64, not representable in u64 */
        return -1;
    }
    out->u64_range = (uint64_t)(range_minus_1 + 1);
    out->kind = ASN_RANGE_NATIVE_U64;

    /* bits = ceil(log2(range)) computed from range_minus_1 */
    bits = 0;
    {
        uintmax_t v = range_minus_1;   /* values 0..range-1 need this many bits */
        while(v) { bits++; v >>= 1; }
    }
    out->range_bits = bits;
    out->effective_bits = bits;
    return 0;
}
/* ---- asn_internal.c ---- */

#ifdef ASN__DEBUG_INDENT_NEEDS_DEFINITION
/*
 * The single definition of the debugging indentation level, shared by all
 * units which refer to it via "extern" in asn_internal.h.  The macro is set
 * by asn_internal.h under exactly the same configuration which declares the
 * variable (ASN_EMIT_DEBUG=1, C99, !ASN_THREAD_SAFE, no ASN_DEBUG override),
 * so the definition can never go out of sync with the declaration.
 */
int asn_debug_indent = 0;
#endif

/*
 * Thread-local encoding recursion depth counters for preventing stack overflow.
 * Separate counters per format allow independent depth tracking.
 */
#if defined(__STDC_VERSION__) && __STDC_VERSION__ >= 201112L && !defined(__STDC_NO_THREADS__)
/* C11 thread support */
thread_local int asn1_encoding_depth = 0;  /* BER/DER */
thread_local int uper_encoding_depth = 0;  /* UPER */
thread_local int aper_encoding_depth = 0;  /* APER */
thread_local int oer_encoding_depth = 0;   /* OER */
thread_local int xer_encoding_depth = 0;   /* XER */
thread_local int jer_encoding_depth = 0;   /* JER */
#elif defined(__GNUC__) || defined(__clang__)
/* GCC/Clang thread-local extension */
__thread int asn1_encoding_depth = 0;  /* BER/DER */
__thread int uper_encoding_depth = 0;  /* UPER */
__thread int aper_encoding_depth = 0;  /* APER */
__thread int oer_encoding_depth = 0;   /* OER */
__thread int xer_encoding_depth = 0;   /* XER */
__thread int jer_encoding_depth = 0;   /* JER */
#elif defined(_MSC_VER)
/* MSVC thread-local */
__declspec(thread) int asn1_encoding_depth = 0;  /* BER/DER */
__declspec(thread) int uper_encoding_depth = 0;  /* UPER */
__declspec(thread) int aper_encoding_depth = 0;  /* APER */
__declspec(thread) int oer_encoding_depth = 0;   /* OER */
__declspec(thread) int xer_encoding_depth = 0;   /* XER */
__declspec(thread) int jer_encoding_depth = 0;   /* JER */
#else
/* No thread-local support, use regular variable (not thread-safe) */
int asn1_encoding_depth = 0;  /* BER/DER */
int uper_encoding_depth = 0;  /* UPER */
int aper_encoding_depth = 0;  /* APER */
int oer_encoding_depth = 0;   /* OER */
int xer_encoding_depth = 0;   /* XER */
int jer_encoding_depth = 0;   /* JER */
#endif

ssize_t
asn__format_to_callback(int (*cb)(const void *, size_t, void *key), void *key,
                        const char *fmt, ...) {
    char scratch[64];
    char *buf = scratch;
    size_t buf_size = sizeof(scratch);
    int wrote;
    int cb_ret;

    do {
        va_list args;
        va_start(args, fmt);

        wrote = vsnprintf(buf, buf_size, fmt, args);
        va_end(args);
        if(wrote < (ssize_t)buf_size) {
            if(wrote < 0) {
                if(buf != scratch) FREEMEM(buf);
                return -1;
            }
            break;
        }

        buf_size <<= 1;
        if(buf == scratch) {
            buf = MALLOC(buf_size);
            if(!buf) {
              return -1;
            }
        } else {
            void *p = REALLOC(buf, buf_size);
            if(!p) {
                FREEMEM(buf);
                return -1;
            }
            buf = p;
        }
    } while(1);

    cb_ret = cb(buf, wrote, key);
    if(buf != scratch) FREEMEM(buf);
    if(cb_ret < 0) {
        return -1;
    }

    return wrote;
}

/* ---- ber_tlv_length.c ---- */
/*-
 * Copyright (c) 2003, 2004 Lev Walkin <vlm@lionet.info>. All rights reserved.
 * Redistribution and modifications are permitted subject to BSD license.
 */

ssize_t
ber_fetch_length(int _is_constructed, const void *bufptr, size_t size,
		ber_tlv_len_t *len_r) {
	const uint8_t *buf = (const uint8_t *)bufptr;
	unsigned oct;

	if(size == 0)
		return 0;	/* Want more */

	oct = *(const uint8_t *)buf;
	if((oct & 0x80) == 0) {
		/*
		 * Short definite length.
		 */
		*len_r = oct;	/* & 0x7F */
		return 1;
	} else {
		ber_tlv_len_t len;
		size_t skipped;

		if(_is_constructed && oct == 0x80) {
			*len_r = -1;	/* Indefinite length */
			return 1;
		}

		if(oct == 0xff) {
			/* Reserved in standard for future use. */
			return -1;
		}

		oct &= 0x7F;	/* Leave only the 7 LS bits */
		for(len = 0, buf++, skipped = 1;
			oct && (++skipped <= size); buf++, oct--) {

			/* Verify that we won't overflow. */
			if(!(len >> ((8 * sizeof(len)) - (8+1)))) {
				len = (len << 8) | *buf;
			} else {
				/* Too large length value. */
				return -1;
			}
		}

		if(oct == 0) {
			if(len < 0 || len > RSSIZE_MAX) {
				/* Length value out of sane range. */
				return -1;
			}

			*len_r = len;
			return skipped;
		}

		return 0;	/* Want more */
	}

}

ssize_t
ber_skip_length(const asn_codec_ctx_t *opt_codec_ctx,
		int _is_constructed, const void *ptr, size_t size) {
	ber_tlv_len_t vlen;	/* Length of V in TLV */
	ssize_t tl;		/* Length of L in TLV */
	ssize_t ll;		/* Length of L in TLV */
	size_t skip;

	/*
	 * Make sure we didn't exceed the maximum stack size.
	 */
	if(ASN__STACK_OVERFLOW_CHECK(opt_codec_ctx))
		return -1;

	/*
	 * Determine the size of L in TLV.
	 */
	ll = ber_fetch_length(_is_constructed, ptr, size, &vlen);
	if(ll <= 0) return ll;

	/*
	 * Definite length.
	 */
	if(vlen >= 0) {
		skip = ll + vlen;
		if(skip > size)
			return 0;	/* Want more */
		return skip;
	}

	/*
	 * Indefinite length!
	 */
	ASN_DEBUG("Skipping indefinite length");
	for(skip = ll, ptr = ((const char *)ptr) + ll, size -= ll;;) {
		ber_tlv_tag_t tag;

		/* Fetch the tag */
		tl = ber_fetch_tag(ptr, size, &tag);
		if(tl <= 0) return tl;

		ll = ber_skip_length(opt_codec_ctx,
			BER_TLV_CONSTRUCTED(ptr),
			((const char *)ptr) + tl, size - tl);
		if(ll <= 0) return ll;

		skip += tl + ll;

		/*
		 * This may be the end of the indefinite length structure,
		 * two consecutive 0 octets.
		 * Check if it is true.
		 */
		if(((const uint8_t *)ptr)[0] == 0
		&& ((const uint8_t *)ptr)[1] == 0)
			return skip;

		ptr = ((const char *)ptr) + tl + ll;
		size -= tl + ll;
	}

	/* UNREACHABLE */
}

size_t
der_tlv_length_serialize(ber_tlv_len_t len, void *bufp, size_t size) {
	size_t required_size;	/* Size of len encoding */
	uint8_t *buf = (uint8_t *)bufp;
	uint8_t *end;
	int i;

	if(len <= 127) {
		/* Encoded in 1 octet */
		if(size) *buf = (uint8_t)len;
		return 1;
	}

	/*
	 * Compute the size of the subsequent bytes.
	 */
	for(required_size = 1, i = 8; i < 8 * (int)sizeof(len); i += 8) {
		if(len >> i)
			required_size++;
		else
			break;
	}

	if(size <= required_size)
		return required_size + 1;

	*buf++ = (uint8_t)(0x80 | required_size);  /* Length of the encoding */

	/*
	 * Produce the len encoding, space permitting.
	 */
	end = buf + required_size;
	for(i -= 8; buf < end; i -= 8, buf++)
		*buf = (uint8_t)(len >> i);

	return required_size + 1;
}

/* ---- ber_tlv_tag.c ---- */
/*-
 * Copyright (c) 2003, 2004 Lev Walkin <vlm@lionet.info>. All rights reserved.
 * Redistribution and modifications are permitted subject to BSD license.
 */
#include <errno.h>

ssize_t
ber_fetch_tag(const void *ptr, size_t size, ber_tlv_tag_t *tag_r) {
	ber_tlv_tag_t val;
	ber_tlv_tag_t tclass;
	size_t skipped;

	if(size == 0)
		return 0;

	val = *(const uint8_t *)ptr;
	tclass = (val >> 6);
	if((val &= 0x1F) != 0x1F) {
		/*
		 * Simple form: everything encoded in a single octet.
		 * Tag Class is encoded using two least significant bits.
		 */
		*tag_r = (val << 2) | tclass;
		return 1;
	}

	/*
	 * Each octet contains 7 bits of useful information.
	 * The MSB is 0 if it is the last octet of the tag.
	 */
	for(val = 0, ptr = ((const char *)ptr) + 1, skipped = 2;
			skipped <= size;
				ptr = ((const char *)ptr) + 1, skipped++) {
		unsigned int oct = *(const uint8_t *)ptr;
		if(oct & 0x80) {
			val = (val << 7) | (oct & 0x7F);
			/*
			 * Make sure there are at least 9 bits spare
			 * at the MS side of a value.
			 */
			if(val >> ((8 * sizeof(val)) - 9)) {
				/*
				 * We would not be able to accommodate
				 * any more tag bits.
				 */
				return -1;
			}
		} else {
			val = (val << 7) | oct;
			*tag_r = (val << 2) | tclass;
			return skipped;
		}
	}

	return 0;	/* Want more */
}


ssize_t
ber_tlv_tag_fwrite(ber_tlv_tag_t tag, FILE *f) {
	char buf[sizeof("[APPLICATION ]") + 32];
	ssize_t ret;

	ret = ber_tlv_tag_snprint(tag, buf, sizeof(buf));
	if(ret >= (ssize_t)sizeof(buf) || ret < 2) {
		errno = EPERM;
		return -1;
	}

	return fwrite(buf, 1, ret, f);
}

ssize_t
ber_tlv_tag_snprint(ber_tlv_tag_t tag, char *buf, size_t size) {
	const char *type = 0;
	int ret;

	switch(tag & 0x3) {
	case ASN_TAG_CLASS_UNIVERSAL:	type = "UNIVERSAL ";	break;
	case ASN_TAG_CLASS_APPLICATION:	type = "APPLICATION ";	break;
	case ASN_TAG_CLASS_CONTEXT:	type = "";		break;
	case ASN_TAG_CLASS_PRIVATE:	type = "PRIVATE ";	break;
	}

	ret = snprintf(buf, size, "[%s%u]", type, ((unsigned)tag) >> 2);
	if(ret <= 0 && size) buf[0] = '\0';	/* against broken libc's */

	return ret;
}

char *
ber_tlv_tag_string(ber_tlv_tag_t tag) {
	static char buf[sizeof("[APPLICATION ]") + 32];

	(void)ber_tlv_tag_snprint(tag, buf, sizeof(buf));

	return buf;
}


size_t
ber_tlv_tag_serialize(ber_tlv_tag_t tag, void *bufp, size_t size) {
	int tclass = BER_TAG_CLASS(tag);
	ber_tlv_tag_t tval = BER_TAG_VALUE(tag);
	uint8_t *buf = (uint8_t *)bufp;
	uint8_t *end;
	size_t required_size;
	size_t i;

	if(tval <= 30) {
		/* Encoded in 1 octet */
		if(size) buf[0] = (tclass << 6) | tval;
		return 1;
	} else if(size) {
		*buf++ = (tclass << 6) | 0x1F;
		size--;
	}

	/*
	 * Compute the size of the subsequent bytes.
	 */
	for(required_size = 1, i = 7; i < 8 * sizeof(tval); i += 7) {
		if(tval >> i)
			required_size++;
		else
			break;
	}

	if(size < required_size)
		return required_size + 1;

	/*
	 * Fill in the buffer, space permitting.
	 */
	end = buf + required_size - 1;
	for(i -= 7; buf < end; i -= 7, buf++)
		*buf = 0x80 | ((tval >> i) & 0x7F);
	*buf = (tval & 0x7F);	/* Last octet without high bit */

	return required_size + 1;
}

