/* ---- uper_decoder.c ---- */

/*
 * Decode a "Production of a complete encoding", X.691#10.1.
 * The complete encoding contains at least one byte, and is an integral
 * multiple of 8 bytes.
 */
asn_dec_rval_t
uper_decode_complete(const asn_codec_ctx_t *opt_codec_ctx,
                     const asn_TYPE_descriptor_t *td, void **sptr,
                     const void *buffer, size_t size) {
    asn_dec_rval_t rval;

	rval = uper_decode(opt_codec_ctx, td, sptr, buffer, size, 0, 0);
	if(rval.consumed) {
		/*
		 * We've always given 8-aligned data,
		 * so convert bits to integral bytes.
		 */
		rval.consumed += 7;
		rval.consumed >>= 3;
	} else if(rval.code == RC_OK) {
		if(size) {
			if(((const uint8_t *)buffer)[0] == 0) {
				rval.consumed = 1;	/* 1 byte */
			} else {
				ASN_DEBUG("Expecting single zeroed byte");
				rval.code = RC_FAIL;
			}
		} else {
			/* Must contain at least 8 bits. */
			rval.code = RC_WMORE;
		}
	}

	return rval;
}

asn_dec_rval_t
uper_decode_complete_canonical(const asn_codec_ctx_t *opt_codec_ctx,
                               const asn_TYPE_descriptor_t *td, void **sptr,
                               const void *buffer, size_t size) {
    asn_codec_ctx_t canonical_ctx;
    
    /* Create a context with canonical flag set */
    if(opt_codec_ctx) {
        canonical_ctx = *opt_codec_ctx;
    } else {
        memset(&canonical_ctx, 0, sizeof(canonical_ctx));
        canonical_ctx.max_stack_size = ASN__DEFAULT_STACK_MAX;
    }
    canonical_ctx.uper_canonical = 1;
    
    return uper_decode_complete(&canonical_ctx, td, sptr, buffer, size);
}

asn_dec_rval_t
uper_decode_canonical(const asn_codec_ctx_t *opt_codec_ctx,
                      const asn_TYPE_descriptor_t *td, void **sptr,
                      const void *buffer, size_t size, int skip_bits, int unused_bits) {
    asn_codec_ctx_t canonical_ctx;
    
    /* Create a context with canonical flag set */
    if(opt_codec_ctx) {
        canonical_ctx = *opt_codec_ctx;
    } else {
        memset(&canonical_ctx, 0, sizeof(canonical_ctx));
        canonical_ctx.max_stack_size = ASN__DEFAULT_STACK_MAX;
    }
    canonical_ctx.uper_canonical = 1;
    
    return uper_decode(&canonical_ctx, td, sptr, buffer, size, skip_bits, unused_bits);
}

asn_dec_rval_t
uper_decode_complete_canonical_lenient(const asn_codec_ctx_t *opt_codec_ctx,
                                      const asn_TYPE_descriptor_t *td, void **sptr,
                                      const void *buffer, size_t size) {
    asn_codec_ctx_t canonical_ctx;
    
    /* Create a context with canonical and lenient flags set */
    if(opt_codec_ctx) {
        canonical_ctx = *opt_codec_ctx;
    } else {
        memset(&canonical_ctx, 0, sizeof(canonical_ctx));
        canonical_ctx.max_stack_size = ASN__DEFAULT_STACK_MAX;
    }
    canonical_ctx.uper_canonical = 1;
    canonical_ctx.uper_canonical_lenient = 1;
    
    return uper_decode_complete(&canonical_ctx, td, sptr, buffer, size);
}

asn_dec_rval_t
uper_decode_canonical_lenient(const asn_codec_ctx_t *opt_codec_ctx,
                             const asn_TYPE_descriptor_t *td, void **sptr,
                             const void *buffer, size_t size, int skip_bits, int unused_bits) {
    asn_codec_ctx_t canonical_ctx;
    
    /* Create a context with canonical and lenient flags set */
    if(opt_codec_ctx) {
        canonical_ctx = *opt_codec_ctx;
    } else {
        memset(&canonical_ctx, 0, sizeof(canonical_ctx));
        canonical_ctx.max_stack_size = ASN__DEFAULT_STACK_MAX;
    }
    canonical_ctx.uper_canonical = 1;
    canonical_ctx.uper_canonical_lenient = 1;
    
    return uper_decode(&canonical_ctx, td, sptr, buffer, size, skip_bits, unused_bits);
}

asn_dec_rval_t
uper_decode(const asn_codec_ctx_t *opt_codec_ctx,
            const asn_TYPE_descriptor_t *td, void **sptr, const void *buffer,
            size_t size, int skip_bits, int unused_bits) {
    asn_codec_ctx_t s_codec_ctx;
	asn_dec_rval_t rval;
	asn_per_data_t pd;

	if(skip_bits < 0 || skip_bits > 7
	|| unused_bits < 0 || unused_bits > 7
	|| (unused_bits > 0 && !size))
		ASN__DECODE_FAILED;

	/*
	 * Stack checker requires that the codec context
	 * must be allocated on the stack.
	 */
	if(opt_codec_ctx) {
		if(opt_codec_ctx->max_stack_size) {
			s_codec_ctx = *opt_codec_ctx;
			opt_codec_ctx = &s_codec_ctx;
		}
	} else {
		/* If context is not given, be security-conscious anyway */
		memset(&s_codec_ctx, 0, sizeof(s_codec_ctx));
		s_codec_ctx.max_stack_size = ASN__DEFAULT_STACK_MAX;
		opt_codec_ctx = &s_codec_ctx;
	}

	/* Fill in the position indicator */
	memset(&pd, 0, sizeof(pd));
	pd.buffer = (const uint8_t *)buffer;
	pd.nboff = skip_bits;
	pd.nbits = 8 * size - unused_bits; /* 8 is CHAR_BIT from <limits.h> */
	if(pd.nboff > pd.nbits)
		ASN__DECODE_FAILED;

	/*
	 * Invoke type-specific decoder.
	 */
	if(!td->op->uper_decoder)
		ASN__DECODE_FAILED;	/* PER is not compiled in */
	rval = td->op->uper_decoder(opt_codec_ctx, td, 0, sptr, &pd);
	if(rval.code == RC_OK) {
		/* Return the number of consumed bits */
		rval.consumed = ((pd.buffer - (const uint8_t *)buffer) << 3)
					+ pd.nboff - skip_bits;
		ASN_DEBUG("PER decoding consumed %ld, counted %ld",
			(long)rval.consumed, (long)pd.moved);
		assert(rval.consumed == pd.moved);
	} else {
		/* PER codec is not a restartable */
		/* Report position where decoding failed */
		rval.consumed = ((pd.buffer - (const uint8_t *)buffer) << 3)
					+ pd.nboff - skip_bits;
		ASN_DEBUG("PER decoding failed at bit %ld (byte %ld, bit %ld)",
			(long)rval.consumed, (long)(rval.consumed >> 3), 
			(long)(rval.consumed & 7));
	}
	return rval;
}
/* ---- uper_encoder.c ---- */

static int _uper_encode_flush_outp(asn_per_outp_t *po);

asn_enc_rval_t
uper_encode(const asn_TYPE_descriptor_t *td,
            const asn_per_constraints_t *constraints, const void *sptr,
            asn_app_consume_bytes_f *cb, void *app_key) {
    asn_per_outp_t po;
    asn_enc_rval_t er = {0,0,0};

    /*
     * Invoke type-specific encoder.
     */
    if(!td || !td->op->uper_encoder)
        ASN__ENCODE_FAILED;	/* PER is not compiled in */

    po.buffer = po.tmpspace;
    po.nboff = 0;
    po.nbits = 8 * sizeof(po.tmpspace);
    po.output = cb ? cb : ignore_output;
    po.op_key = app_key;
    po.flushed_bytes = 0;

    er = td->op->uper_encoder(td, constraints, sptr, &po);
    if(er.encoded != -1) {
        size_t bits_to_flush;

        bits_to_flush = ((po.buffer - po.tmpspace) << 3) + po.nboff;

        /* Set number of bits encoded to a firm value */
        er.encoded = (po.flushed_bytes << 3) + bits_to_flush;

        if(_uper_encode_flush_outp(&po)) ASN__ENCODE_FAILED;
    }

    return er;
}

/*
 * Argument type and callback necessary for uper_encode_to_buffer().
 */
typedef struct enc_to_buf_arg {
	void *buffer;
	size_t left;
} enc_to_buf_arg;
static int encode_to_buffer_cb(const void *buffer, size_t size, void *key) {
	enc_to_buf_arg *arg = (enc_to_buf_arg *)key;

	if(arg->left < size)
		return -1;	/* Data exceeds the available buffer size */

	memcpy(arg->buffer, buffer, size);
	arg->buffer = ((char *)arg->buffer) + size;
	arg->left -= size;

	return 0;
}

asn_enc_rval_t
uper_encode_to_buffer(const asn_TYPE_descriptor_t *td,
                      const asn_per_constraints_t *constraints,
                      const void *sptr, void *buffer, size_t buffer_size) {
    enc_to_buf_arg key;

    key.buffer = buffer;
    key.left = buffer_size;

    if(td) ASN_DEBUG("Encoding \"%s\" using UNALIGNED PER", td->name);

    return uper_encode(td, constraints, sptr, encode_to_buffer_cb, &key);
}

ssize_t
uper_encode_to_new_buffer(const asn_TYPE_descriptor_t *td,
                          const asn_per_constraints_t *constraints,
                          const void *sptr, void **buffer_r) {
    asn_enc_rval_t er = {0,0,0};
	enc_dyn_arg key;

	memset(&key, 0, sizeof(key));

	er = uper_encode(td, constraints, sptr, encode_dyn_cb, &key);
	switch(er.encoded) {
	case -1:
		FREEMEM(key.buffer);
		return -1;
	case 0:
		FREEMEM(key.buffer);
		key.buffer = MALLOC(1);
		if(key.buffer) {
			*(char *)key.buffer = '\0';
			*buffer_r = key.buffer;
			return 1;
		} else {
			return -1;
		}
	default:
		*buffer_r = key.buffer;
		ASN_DEBUG("Complete encoded in %ld bits", (long)er.encoded);
		return ((er.encoded + 7) >> 3);
	}
}

/*
 * Internally useful functions.
 */

/* Flush partially filled buffer */
static int
_uper_encode_flush_outp(asn_per_outp_t *po) {
	uint8_t *buf;

	if(po->nboff == 0 && po->buffer == po->tmpspace)
		return 0;

	buf = po->buffer + (po->nboff >> 3);
	/* Make sure we account for the last, partially filled */
	if(po->nboff & 0x07) {
		buf[0] &= 0xff << (8 - (po->nboff & 0x07));
		buf++;
	}

	return po->output(po->tmpspace, buf - po->tmpspace, po->op_key);
}
